// Generates (or, with --check, verifies) every language's message bindings
// from protocol/asyncapi.json + contract/adapter-protocol.schema.json.
//   node tools/generate.ts          write the generated files
//   node tools/generate.ts --check  fail if any generated file is stale or missing
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { InputData, JSONSchemaInput, JSONSchemaStore, quicktype, type JSONSchema } from "quicktype-core";
import openapiTS, { astToString, type OpenAPI3 } from "openapi-typescript";
import { buildBundle, type Bundle } from "./bundle.ts";
import { targets, type Target } from "./targets.ts";
import typescriptManifest from "../packages/typescript/package.json" with { type: "json" };

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const openapiPath = join(root, "protocol/tron.openapi.json");
const asyncapiPath = join(root, "protocol/asyncapi.json");
const adapterSchemaPath = join(root, "contract/adapter-protocol.schema.json");

function banner(target: Target, bundle: Bundle): string {
  return [
    `${target.comment} GENERATED by tools/generate.ts from protocol/asyncapi.json (runner protocol ${bundle.protocolVersion},`,
    `${target.comment} document ${bundle.documentVersion}) and contract/adapter-protocol.schema.json. DO NOT EDIT:`,
    `${target.comment} change the sources and run \`npm run generate\`; CI rejects stale output.`,
    "",
  ].join("\n");
}

const BUNDLE_ADDRESS = "bundle.json";

// All top-level types are pointers into ONE schema document, so a definition
// referenced by several of them is generated once under its own name.
class BundleStore extends JSONSchemaStore {
  private readonly document: JSONSchema;
  constructor(bundle: Bundle) {
    super();
    this.document = { definitions: bundle.definitions } as JSONSchema;
  }
  async fetch(address: string): Promise<JSONSchema | undefined> {
    return address === BUNDLE_ADDRESS ? this.document : undefined;
  }
}

async function renderBindings(target: Target, bundle: Bundle): Promise<string> {
  const input = new JSONSchemaInput(new BundleStore(bundle));
  for (const name of bundle.topLevel) {
    input.addSource({ name, uris: [`${BUNDLE_ADDRESS}#/definitions/${name}`] });
  }
  const inputData = new InputData();
  inputData.addInput(input);
  const result = await quicktype({
    inputData,
    lang: target.quicktypeLanguage,
    rendererOptions: target.rendererOptions,
    leadingComments: [],
  });
  const source = result.lines.join("\n") + "\n";
  return banner(target, bundle) + (target.postProcess ? target.postProcess(source) : source);
}

export async function render(): Promise<Map<string, string>> {
  const bundle = buildBundle(asyncapiPath, adapterSchemaPath);
  const files = new Map<string, string>();
  for (const target of targets) {
    files.set(join(target.directory, target.bindingsFile), await renderBindings(target, bundle));
    files.set(
      join(target.directory, target.versionFile),
      banner(target, bundle) + target.versionSource({ protocol: bundle.protocolVersion, document: bundle.documentVersion, channel: bundle.channelAddress }),
    );
  }
  // The TypeScript package announces the version package.json records, so the constant is derived, never retyped.
  files.set(
    "packages/typescript/src/generated/sdk-version.ts",
    `// GENERATED by tools/generate.ts from packages/typescript/package.json. DO NOT EDIT: run \`npm run generate\`.\n/** This package's semantic version, announced to Tron. */\nexport const SDK_VERSION = ${JSON.stringify(typescriptManifest.version)};\n`,
  );
  // Tron's REST types, for the conformance harness only (never a package).
  // adr2-opaque: schema-generation input; openapi-typescript consumes the whole OpenAPI document and our code reads nothing from it
  const openapi = JSON.parse(readFileSync(openapiPath, "utf8")) as OpenAPI3;
  const rest = astToString(await openapiTS(openapi));
  files.set(
    "conformance/generated/tron-api.d.ts",
    `// GENERATED by tools/generate.ts from protocol/tron.openapi.json. DO NOT EDIT: run \`npm run generate\`.\n${rest}`,
  );
  return files;
}

const check = process.argv.includes("--check");
const files = await render();
const stale: string[] = [];
for (const [relative, content] of files) {
  const path = join(root, relative);
  const current = existsSync(path) ? readFileSync(path, "utf8") : undefined;
  if (current === content) continue;
  if (check) {
    stale.push(`${relative} ${current === undefined ? "is missing" : "is stale"}`);
  } else {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, content);
    console.log(`wrote ${relative}`);
  }
}
if (stale.length > 0) {
  console.error(`generated bindings are out of date (run \`npm run generate\`):\n  ${stale.join("\n  ")}`);
  process.exit(1);
}
if (check) console.log(`generated bindings are up to date (${files.size} files)`);
